theme.css:
/* theme: Brass Tacks | A market-driven day of spin-offs, stock gains, and lowered expectations — sharp angles, industrial type, and ledger-book structure. */
/* mood: neutral */
/* layout: hero=classic; political-news=numbered/stack; financial-news=outline/grid-2; entertainment-news=lede/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=timeline/stack */

.diary-page {
  --paper: #fafafa;
  --paper-alt: #f0f0f0;
  --ink: #1a1a1a;
  --ink-soft: #3d3d3d;
  --muted: #666666;
  --accent: #2b2b2b;
  --accent-ink: #ffffff;
  --rule: #d4d4d4;
  --font-display: var(--ff-archivo-black), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;
}

/* Header: industrial ledger style, no frills */
.diary-page[data-hero="classic"] .diary-hero {
  background: var(--paper);
  border-bottom: 3px double var(--ink);
  position: relative;
}

.diary-page[data-hero="classic"] .diary-hero::after {
  content: "◆";
  position: absolute;
  bottom: -0.65em;
  right: 1.5rem;
  font-size: 1.2rem;
  color: var(--accent);
}

.diary-page[data-hero="classic"] .diary-hero-inner {
  padding-block: 1.75rem 2.5rem;
}

.diary-page .diary-crumbs a {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--muted);
  text-transform: uppercase;
}

.diary-page .diary-kicker {
  margin-top: 1.5rem;
  font-family: var(--font-ui);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
}

.diary-page .diary-title {
  margin-top: 0.5rem;
  max-width: none;
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 5.5vw, 4.5rem);
  font-weight: 400;
  line-height: 1.02;
  letter-spacing: 0.01em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-summary {
  margin-top: 1.25rem;
  max-width: 44rem;
  font-size: clamp(1.05rem, 1.6vw, 1.25rem);
  line-height: 1.6;
  color: var(--ink-soft);
}

.diary-page .diary-theme-note {
  margin-top: 1.25rem;
  font-family: var(--font-ui);
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--muted);
}

.diary-page .diary-theme-name {
  display: inline-block;
  margin-right: 0.5rem;
  padding: 0.15rem 0.5rem;
  border: 1px solid var(--accent);
  border-radius: 0;
  background: none;
  color: var(--accent);
  font-weight: 600;
  text-transform: uppercase;
}

/* Contents strip: sharp, angular, tabbed */
.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--ink);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  font-family: var(--font-ui);
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
  letter-spacing: 0.04em;
}

.diary-page .diary-toc-link.is-active {
  color: var(--ink);
  font-weight: 700;
}

.diary-page .diary-toc-number {
  font-size: 0.7rem;
  color: var(--accent);
  font-weight: 700;
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left: 3px solid var(--ink);
  }

  .diary-page .diary-toc-link {
    margin-left: -3px;
    border-left: 3px solid transparent;
    padding-left: 0.9rem;
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
    background: linear-gradient(90deg, var(--paper-alt) 0%, transparent 100%);
  }
}

/* Section headers: numbered, ruled, tight */
.diary-page .diary-section {
  padding-block: 2.5rem;
  border-top: 1px solid var(--rule);
}

.diary-page .diary-section:first-child {
  border-top: 0;
  padding-top: 1.5rem;
}

.diary-page .diary-section-head {
  margin-bottom: 1.5rem;
  border-bottom: 2px solid var(--ink);
  padding-bottom: 0.5rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-display);
  font-size: 0.85rem;
  letter-spacing: 0.1em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 2.8vw, 2.25rem);
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--ink);
}

/* Political News: numbered, stacked, with index rails */
.diary-page [data-section="political-news"] .diary-card {
  border-left: 4px solid var(--ink);
  margin-left: 0;
}

.diary-page [data-section="political-news"] .diary-card-inner {
  padding-left: 1.25rem;
}

.diary-page [data-section="political-news"] .diary-card-index {
  font-family: var(--font-display);
  font-size: 2.5rem;
  line-height: 0.9;
  color: var(--accent);
  margin-bottom: 0.5rem;
}

.diary-page [data-section="political-news"] .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--ink);
}

/* Financial News: outlined cards, grid, sharp corners */
.diary-page [data-section="financial-news"] .diary-card-inner {
  padding: 1.25rem;
  border: 1px solid var(--ink);
  background: var(--paper);
  box-shadow: 4px 4px 0 var(--accent);
  border-radius: 0;
}

.diary-page [data-section="financial-news"] .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--ink);
  padding-bottom: 0.35rem;
  border-bottom: 1px solid var(--rule);
}

.diary-page [data-section="financial-news"] .diary-card-body {
  font-size: 1.02rem;
  line-height: 1.65;
}

/* Entertainment: lede cards in masonry, magazine feel */
.diary-page [data-section="entertainment-news"] .diary-card-lede {
  padding-left: 0;
  border-left: 0;
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.5rem;
  font-family: var(--font-display);
  font-size: 1.15rem;
  line-height: 1.4;
  color: var(--ink);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.diary-page [data-section="entertainment-news"] .diary-card-inner {
  padding: 1rem;
  background: var(--paper-alt);
  border-left: 3px solid var(--accent);
}

.diary-page [data-section="entertainment-news"] .diary-card-body {
  font-size: 1rem;
  line-height: 1.6;
}

/* Music Releases: plain, no boxes, editorial flow */
.diary-page [data-section="music-releases"] .diary-card {
  max-width: 46rem;
}

.diary-page [data-section="music-releases"] .diary-card-inner {
  padding-block: 1rem;
}

.diary-page [data-section="music-releases"] + .diary-card {
  border-top: 1px solid var(--rule);
}

/* Stock Analysis: stat cards, grid-3, ledgers */
.diary-page [data-section="stock-analysis"] .diary-card-inner {
  padding: 1.25rem;
  border: 1px solid var(--rule);
  border-top: 4px solid var(--accent);
  background: var(--paper);
  position: relative;
}

.diary-page [data-section="stock-analysis"] .diary-card::before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 0;
  height: 0;
  border-top: 1.5rem solid var(--accent);
  border-left: 1.5rem solid transparent;
}

.diary-page [data-section="stock-analysis"] .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 10cqi, 2.75rem);
  font-weight: 400;
  line-height: 1;
  color: var(--accent);
  margin-bottom: 0.25rem;
}

.diary-page [data-section="stock-analysis"] .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink);
}

.diary-page [data-section="stock-analysis"] .diary-card-body {
  font-size: 0.98rem;
  line-height: 1.55;
}

/* Markets wrap: strip of dark bands */
.diary-page .diary-markets-wrap {
  background: var(--paper-alt);
  padding: 1.25rem;
  border: 1px solid var(--rule);
}

.diary-page .diary-markets-label {
  font-family: var(--font-ui);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.diary-page .diary-spark {
  background: var(--paper);
  border: 1px solid var(--rule);
  border-radius: 0;
  font-family: var(--font-ui);
}

.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

/* Outlook: timeline cards, dotted rail */
.diary-page [data-section="outlook"] .diary-card-inner {
  padding-left: 2rem;
  position: relative;
}

.diary-page [data-section="outlook"] .diary-card-inner::before {
  content: "";
  position: absolute;
  left: 0.35rem;
  top: 0;
  bottom: -1.5rem;
  width: 2px;
  background: repeating-linear-gradient(
    to bottom,
    var(--accent) 0px,
    var(--accent) 4px,
    transparent 4px,
    transparent 8px
  );
}

.diary-page [data-section="outlook"] .diary-card-inner::after {
  content: "";
  position: absolute;
  left: 0;
  top: 0.35rem;
  width: 0.7rem;
  height: 0.7rem;
  background: var(--accent);
  transform: rotate(45deg);
}

.diary-page [data-section="outlook"] .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--ink);
}

/* Body text tuning */
.diary-page .diary-prose {
  font-size: 1.1rem;
  line-height: 1.7;
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  font-family: var(--font-ui);
  font-size: 0.65em;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
  border-bottom: 1px solid var(--accent);
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-card-thread {
  border: 1px solid var(--accent);
  border-radius: 0;
  font-family: var(--font-ui);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent);
  background: var(--paper);
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Footer: ruled like a ledger */
.diary-page .diary-footer {
  border-top: 1px solid var(--ink);
  font-family: var(--font-ui);
  font-size: 0.8rem;
  color: var(--muted);
}

.diary-page .diary-footer a {
  font-weight: 700;
  color: var(--ink);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Drop cap: square, architectural */
.diary-page .diary-section:first-child .diary-card--plain:first-child .diary-prose > p:first-of-type::first-letter {
  float: left;
  margin: 0.08em 0.15em 0 0;
  font-family: var(--font-display);
  font-size: 3.2em;
  font-weight: 400;
  line-height: 0.75;
  color: var(--accent);
  background: var(--paper-alt);
  padding: 0.2em 0.25em;
  border: 1px solid var(--accent);
}

/* Subtle entrance: only the hero title */
@media (prefers-reduced-motion: no-preference) {
  .diary-page .diary-title {
    animation: diary-slide-up 0.6s ease-out both;
  }
}

@keyframes diary-slide-up {
  from {
    opacity: 0;
    transform: translateY(1rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
